INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES ("2023/11/16 15:00:00", 54, 20047003, 2.801, "受け取ることができる\n報酬があるようです\n確認してみてください", "カリン", -416.5, 190801, 1, "2030/01/01 14:59:59", 0.0, 20047, 2, 3);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES ("2023/11/16 15:00:00", 54, 20047004, 0.0, "報酬がもらえますよ！\nチェックしてみてください", "カリン", -416.5, 190801, 2, "2030/01/01 14:59:59", 0.0, 20047, 2, 4);
INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES ("2023/11/16 15:00:00", 57, 20047005, 0.0, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", "カリン", -416.5, 190801, 1, "2030/01/01 14:59:59", 0.0, 20047, 1, 5);
