INSERT INTO `v1_9b2c974a63eedf199276ac099bbb407fc591f4795f53f246e3030bc480200b60` VALUES ("2023/11/16 15:00:00", 56, 20047008, 1.539, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", "カリン", -363.0, 190801, 2, "2030/01/01 14:59:59", 0.0, 20047, 1, 3);
